import { useRef, useState, type ComponentProps, type ReactNode } from "react";
import { Copy, Pencil, RotateCcw } from "lucide-react";
import { cn } from "./utils";

type MessageActionHandler = (
    messageId?: string,
) => void | Promise<void>;

type MessageAction = {
    id: string;
    label: string;
    icon?: ReactNode;
    onAction: MessageActionHandler;
    disabled?: boolean;
};

type MessageActionKind = "copy" | "edit" | "retry";

type MessageActionsProps = {
    messageId?: string;
    actions?: readonly MessageAction[];
    onCopy?: MessageActionHandler;
    onEdit?: MessageActionHandler;
    onRetry?: MessageActionHandler;
    children?: ReactNode;
    errorMessage?: string;
    className?: string;
};

type MessageProps = ComponentProps<"div"> & {
    from: "user" | "assistant" | "system";
    actions?: ReactNode;
};

function actionErrorText(error: unknown, fallback: string) {
    return error instanceof Error && error.message.trim()
        ? error.message : fallback;
}

function MessageActions({
    messageId,
    actions = [],
    onCopy,
    onEdit,
    onRetry,
    children,
    errorMessage = "메시지 작업을 완료하지 못했습니다.",
    className,
}: MessageActionsProps) {
    const pendingMessages = useRef(new Set<string | undefined>());
    const [, setPendingRevision] = useState(0);
    const [errorsByMessage, setErrorsByMessage] = useState(
        new Map<string | undefined, string>(),
    );
    const hasChildren = children !== null && children !== undefined;
    const pending = pendingMessages.current.has(messageId);
    const error = errorsByMessage.get(messageId) ?? null;
    const actionList: Array<MessageAction & { kind?: MessageActionKind }> = [];

    if (onCopy) actionList.push({
        id: "copy", kind: "copy", label: "복사", icon: <Copy
            aria-hidden="true" size={16} />, onAction: onCopy,
    });
    if (onEdit) actionList.push({
        id: "edit", kind: "edit", label: "편집", icon: <Pencil
            aria-hidden="true" size={16} />, onAction: onEdit,
    });
    if (onRetry) actionList.push({
        id: "retry", kind: "retry", label: "재시도", icon: <RotateCcw
            aria-hidden="true" size={16} />, onAction: onRetry,
    });
    actionList.push(...actions);

    if (actionList.length === 0 && !hasChildren) return null;

    async function run(action: MessageAction) {
        if (pendingMessages.current.has(messageId) || action.disabled) return;
        pendingMessages.current.add(messageId);
        setPendingRevision((revision) => revision + 1);
        setErrorsByMessage((previous) => {
            const next = new Map(previous);
            next.delete(messageId);
            return next;
        });
        try {
            await action.onAction(messageId);
        } catch (reason) {
            setErrorsByMessage((previous) => new Map(previous).set(
                messageId, actionErrorText(reason, errorMessage),
            ));
        } finally {
            pendingMessages.current.delete(messageId);
            setPendingRevision((revision) => revision + 1);
        }
    }

    return (
        <div role="group" aria-label="메시지 작업"
            aria-busy={pending}
            data-ui="message-actions"
            className={cn("flex flex-wrap items-center gap-1", className)}>
            {actionList.map((action, index) => (
                <button type="button"
                    key={`${action.id}:${index}`}
                    aria-label={action.label}
                    title={action.label}
                    disabled={action.disabled || pending}
                    className={
                        "inline-flex h-8 min-w-8 items-center justify-center " +
                        "gap-1 rounded-sm border border-transparent px-2 " +
                        "text-xs text-muted hover:bg-surface-subtle " +
                        "focus-visible:outline-2 focus-visible:outline-focus " +
                        "disabled:cursor-not-allowed disabled:opacity-50"
                    }
                    onClick={() => void run(action)}>
                    {action.icon ?? action.label}
                    {action.kind && <span className="sr-only">
                        {action.label}
                    </span>}
                </button>
            ))}
            {children}
            {error && <p role="alert" className="m-0 text-xs text-danger">
                {error}
            </p>}
        </div>
    );
}

function Message({ from, className, actions, children, ...props }: MessageProps) {
    const labels = {
        user: "사용자",
        assistant: "응답",
        system: "시스템",
    };

    return (
        <div
            role="group"
            aria-label={`${labels[from]} 메시지`}
            data-ui="message"
            className={cn(
                "group flex max-w-[92%] flex-col gap-1 text-sm",
                from === "user" && "ml-auto items-end",
                className,
            )}
            {...props}
            data-from={from}
        >
            {children}
            {actions}
        </div>
    );
}

function MessageContent({ className, ...props }: ComponentProps<"div">) {
    return (
        <div
            data-surface="message"
            className={cn(
                "min-w-0 rounded-sm border border-border bg-surface " +
                "p-[var(--space-3)] [overflow-wrap:anywhere] " +
                "group-data-[from=user]:border-message-user " +
                "group-data-[from=user]:bg-message-user " +
                "group-data-[from=user]:text-message-user-foreground",
                className,
            )}
            {...props}
        />
    );
}

export { Message, MessageActions, MessageContent };
export type {
    MessageAction, MessageActionHandler, MessageActionsProps,
    MessageActionKind, MessageProps,
};
